import React, { useState, useEffect, useCallback, useRef } from "react";
import Sidebar from "./Sidebar";
import ChatWindow from "./ChatWindow";
import MobileDrawer from "./MobileDrawer";
import { useAuth } from "../context/AuthContext";
import { getUserRooms } from "../services/api";
import { wsService } from "../services/websocket";

export default function ChatApp() {
  const { token, username } = useAuth();
  const [rooms, setRooms]           = useState([]);
  const [activeRoom, setActiveRoom] = useState(null);
  const [messages, setMessages]     = useState({});   // roomId → msg[]
  const [wsConnected, setWsConnected] = useState(false);
  const [drawerOpen, setDrawerOpen] = useState(false);
  const activeRoomRef = useRef(null); // mirror for use inside callbacks

  // Keep ref in sync
  useEffect(() => { activeRoomRef.current = activeRoom; }, [activeRoom]);

  // Load rooms on mount
  useEffect(() => {
    if (!username) return;
    getUserRooms(username).then(({ data }) => setRooms(data)).catch(() => {});
  }, [username]);

  // Connect WebSocket
  useEffect(() => {
    if (!token) return;

    wsService.connect(
      token,
      () => {
        setWsConnected(true);

        // ✅ FIX 16: Re-subscribe to the currently open room after reconnect.
        //            wsService.subscribeRoom already handles this via pendingSubs,
        //            but calling it here also ensures the UI state (wsConnected)
        //            is updated before the next message arrives.
        const room = activeRoomRef.current;
        if (room) {
          wsService.subscribeRoom(room.id, (msg) =>
            handleNewMessage(room.id, [msg], false)
          );
        }
      },
      () => setWsConnected(false)
    );

    return () => wsService.disconnect();
  }, [token]);

  const handleNewMessage = useCallback((roomId, msgs, replace = false) => {
    setMessages((prev) => ({
      ...prev,
      // ✅ FIX 17: Deduplicate messages by id to prevent doubles when history
      //            is reloaded while a live subscription is also active.
      [roomId]: replace
        ? msgs
        : dedup([...(prev[roomId] || []), ...msgs]),
    }));
  }, []);

  const handleSelectRoom = (room) => {
    setActiveRoom(room);
    setDrawerOpen(false);

    // Subscribe — wsService queues it if not yet connected
    wsService.subscribeRoom(room.id, (msg) =>
      handleNewMessage(room.id, [msg], false)
    );
  };

  const handleRoomsChange = (newRoom) => {
    setRooms((prev) => {
      const exists = prev.find((r) => r.id === newRoom.id);
      return exists ? prev : [newRoom, ...prev];
    });
  };

  return (
    <div className="flex h-full w-full overflow-hidden bg-crisp-bg">
      {/* Desktop sidebar */}
      <div className="hidden lg:flex h-full">
        <Sidebar
          rooms={rooms}
          activeRoomId={activeRoom?.id}
          onSelectRoom={handleSelectRoom}
          onRoomsChange={handleRoomsChange}
          wsConnected={wsConnected}
          messages={messages}
        />
      </div>

      {/* Mobile drawer */}
      <MobileDrawer open={drawerOpen} onClose={() => setDrawerOpen(false)}>
        <Sidebar
          rooms={rooms}
          activeRoomId={activeRoom?.id}
          onSelectRoom={handleSelectRoom}
          onRoomsChange={handleRoomsChange}
          wsConnected={wsConnected}
          messages={messages}
        />
      </MobileDrawer>

      {/* Main area */}
      <main className="flex-1 flex flex-col min-w-0 h-full">
        {/* Mobile top bar */}
        <div className="flex items-center gap-3 px-4 py-3 bg-crisp-surface border-b
          border-crisp-border lg:hidden">
          <button
            onClick={() => setDrawerOpen(true)}
            className="w-9 h-9 rounded-xl bg-crisp-card border border-crisp-border
              flex items-center justify-center"
          >
            <svg className="w-5 h-5 text-crisp-sub" fill="none" viewBox="0 0 24 24"
              stroke="currentColor" strokeWidth={2}>
              <line x1="3" y1="12" x2="21" y2="12"/>
              <line x1="3" y1="6"  x2="21" y2="6"/>
              <line x1="3" y1="18" x2="21" y2="18"/>
            </svg>
          </button>
          <div className="w-8 h-8 bg-crisp-accent rounded-xl flex items-center justify-center
            font-mono font-bold text-white text-sm">C</div>
          <span className="font-display font-bold text-base text-crisp-text">Crisp</span>
          <span className={`ml-auto w-2 h-2 rounded-full
            ${wsConnected ? "bg-crisp-green" : "bg-crisp-amber animate-pulse2"}`} />
        </div>

        {/* ✅ Pass wsConnected down so ChatWindow can react to it */}
        <ChatWindow
          room={activeRoom}
          messages={activeRoom ? messages[activeRoom.id] : null}
          onNewMessage={handleNewMessage}
          wsConnected={wsConnected}
        />
      </main>
    </div>
  );
}

// Remove duplicate messages (same id)
function dedup(msgs) {
  const seen = new Set();
  return msgs.filter((m) => {
    if (!m.id) return true; // no id = keep
    if (seen.has(m.id)) return false;
    seen.add(m.id);
    return true;
  });
}
